use litex::ast::stmt::Stmt;
use litex::execute::execute_fact_stmt::{VerifyFactResult, VerifyState};
use litex::execute::execute_fact_stmt::verify_atomic_fact::verify_equality::{
    EqualFactSearchedProof, VerifyEqualityResult, EqualitySearchProofByObjectDefinition,
};
use litex::execute::execute_fact_stmt::verify_atomic_fact::verify_equality::by_object_definition::by_fn_application::result::EqualitySearchProofByFnApplicationObjectDefinition;
use litex::execute::execute_fact_stmt::verify_atomic_fact::verify_equality::result::{EqualFactSearchedProofByEquivalenceClass, PeerEqualitySearchedProof};
use litex::launch_command::{LaunchCommand, OutputLanguage};
use litex::runtime::Runtime;
use litex::tokenize::Tokenizer;

const DEFINITION: &str = "have fn f(n N) N by induc n from 0:\n    case n = 0: 0\n    case n >= 1: f(n - 1)\n";

fn walk(result: &VerifyFactResult, depth: usize) {
    let VerifyFactResult::Equality(result) = result else { return };
    let VerifyEqualityResult::Success(proof) = result.as_ref() else {
        println!("{}FAILED", "  ".repeat(depth));
        return;
    };
    println!("{}{} = {}", "  ".repeat(depth), proof.fact.left.readable_string(), proof.fact.right.readable_string());
    match &proof.searched_proof {
        EqualFactSearchedProof::ByObjectDefinition(EqualitySearchProofByObjectDefinition::ByFnApplication(EqualitySearchProofByFnApplicationObjectDefinition::HaveFnByInduc(p))) => {
            println!("{}unfold -> {}", "  ".repeat(depth), p.expanded_body.readable_string());
            walk(&p.residual_equal, depth + 1);
        }
        EqualFactSearchedProof::ByTheyAreTheSame(_) => println!("{}identity", "  ".repeat(depth)),
        EqualFactSearchedProof::ByEquivalenceClass(p) => {
            println!("{}equivalence class", "  ".repeat(depth));
            if let EqualFactSearchedProofByEquivalenceClass::ViaPeers(p) = p {
                println!("{}bridge {} = {}", "  ".repeat(depth), p.bridge.fact.left.readable_string(), p.bridge.fact.right.readable_string());
                if let PeerEqualitySearchedProof::ByMatchingOneArgByOne(p) = &p.bridge.searched_proof {
                    for child in &p.corresponding_arg_equal_proofs { walk(child, depth + 1); }
                }
            }
        }
        EqualFactSearchedProof::ByMatchingOneArgByOne(p) => {
            println!("{}matching args", "  ".repeat(depth));
            for child in &p.corresponding_arg_equal_proofs { walk(child, depth + 1); }
        }
        EqualFactSearchedProof::ByBuiltinRule(_) => println!("{}builtin", "  ".repeat(depth)),
        _ => println!("{}other route", "  ".repeat(depth)),
    }
}

fn check(prefix: &str, goal: &str, rounds: u8) {
    let mut runtime = Runtime::new(LaunchCommand::Eval {
        code: String::new(), session: false, strict: true, language: OutputLanguage::English,
    });
    let run = runtime.run_litex_code(&format!("{DEFINITION}{prefix}")).unwrap();
    assert!(run.success);
    let tokens = Tokenizer::new().tokenize(goal, runtime.current_file.clone()).unwrap();
    let statements = runtime.parse(&tokens).unwrap();
    let Stmt::Fact(fact) = &statements[0] else { panic!("expected fact") };
    let mut state = VerifyState::top_level();
    state.can_use_builtin_rule_round = rounds;
    state.store_well_defined_fact = false;
    let result = runtime.verify_fact(fact, state).unwrap();
    println!("CHECK prefix={prefix:?} goal={goal:?} rounds={rounds} success={} wd_failed={}", !result.is_failed(), result.is_wd_failed());
    walk(&result, 0);
}

fn main() {
    check("", "f(1) = 0", 3);
    check("f(0) = 0\nf(1) = 0\n", "f(2) = 0", 3);
    check("f(0) = 0\nf(1) = 0\n", "f(2) = 0", 4);
    check("f(0) = 0\nf(1) = 0\n2 - 1 = 1\n", "f(2) = 0", 3);
    check("", "(2 - 1) - 1 = 0", 0);
    check("", "(2 - 1) - 1 = 0", 1);
    check("f(0) = 0\nf(1) = 0\n", "f(2 - 1) = f(1)", 0);
    check("f(0) = 0\nf(1) = 0\n2 - 1 = 1\n", "f(2 - 1) = f(1)", 0);
}
